SELECT id, customer_id, device, browser, started_at, country, ROW_NUMBER() OVER (PARTITION BY country, browser ORDER BY started_at DESC, id) AS event_seq, FIRST_VALUE(browser, TRUE) OVER w_recent AS first_known_browser, ROW_NUMBER() OVER (ORDER BY started_at DESC, id) AS row_seq, LAST_VALUE(country) IGNORE NULLS OVER w_recent AS last_known_country FROM sessions WINDOW w_recent AS (PARTITION BY country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
